#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
HANDOFF_DIR="${HANDOFF_DIR:-$ROOT_DIR/reports/tv-box-handoff}"
REPORT_PATH="${REPORT_PATH:-$ROOT_DIR/reports/tv-box-acceptance-latest.md}"
HANDOFF_LATEST_PATH_FILE="${HANDOFF_LATEST_PATH_FILE:-$ROOT_DIR/reports/tv-box-handoff-latest-path.txt}"
HANDOFF_LATEST_ARCHIVE_FILE="${HANDOFF_LATEST_ARCHIVE_FILE:-$ROOT_DIR/reports/tv-box-handoff-latest-archive.txt}"
SUPPORT_LATEST_PATH_FILE="${SUPPORT_LATEST_PATH_FILE:-$ROOT_DIR/reports/tv-box-support-latest-path.txt}"
SUPPORT_LATEST_ARCHIVE_FILE="${SUPPORT_LATEST_ARCHIVE_FILE:-$ROOT_DIR/reports/tv-box-support-latest-archive.txt}"

cd "$ROOT_DIR"

checked=0

pass() {
  checked=$((checked + 1))
  printf 'OK: %s\n' "$1"
}

fail() {
  printf 'ERROR: %s\n' "$1" >&2
  exit 1
}

require_file() {
  local path="$1"
  local label="$2"
  [[ -f "$path" ]] || fail "$label is missing: $path"
  pass "$label exists"
}

require_dir() {
  local path="$1"
  local label="$2"
  [[ -d "$path" ]] || fail "$label is missing: $path"
  pass "$label exists"
}

require_executable() {
  local path="$1"
  local label="$2"
  [[ -x "$path" ]] || fail "$label is not executable: $path"
  pass "$label is executable"
}

require_text() {
  local path="$1"
  local needle="$2"
  local label="$3"
  grep -Fq -- "$needle" "$path" || fail "$label not found in $path"
  pass "$label"
}

require_package_script() {
  local script_name="$1"
  node -e "const scripts=require('./package.json').scripts||{}; process.exit(scripts[process.argv[1]] ? 0 : 1)" "$script_name" \
    || fail "package.json script is missing: $script_name"
  pass "package.json exposes $script_name"
}

json_value() {
  local path="$1"
  local key_path="$2"
  node -e '
const fs = require("fs")
const data = JSON.parse(fs.readFileSync(process.argv[1], "utf8"))
const value = process.argv[2].split(".").reduce((current, key) => current && current[key], data)
if (value === undefined || value === null) process.exit(1)
process.stdout.write(String(value))
' "$path" "$key_path"
}

sha256_file() {
  local path="$1"
  node -e '
const fs = require("fs")
const crypto = require("crypto")
process.stdout.write(crypto.createHash("sha256").update(fs.readFileSync(process.argv[1])).digest("hex"))
' "$path"
}

require_equal() {
  local actual="$1"
  local expected="$2"
  local label="$3"
  [[ "$actual" == "$expected" ]] || fail "$label mismatch: expected $expected, got $actual"
  pass "$label"
}

require_not_equal() {
  local actual="$1"
  local forbidden="$2"
  local label="$3"
  [[ "$actual" != "$forbidden" ]] || fail "$label unexpectedly equals $forbidden"
  pass "$label"
}

require_archive_member() {
  local archive_path="$1"
  local member="$2"
  local label="$3"
  local listing

  if [[ "$archive_path" == *.zip ]] && command -v unzip >/dev/null 2>&1; then
    listing="$(unzip -l "$archive_path")"
    grep -Fq "$member" <<< "$listing" || fail "$label missing from archive: $member"
    pass "$label"
    return
  fi

  if [[ "$archive_path" == *.tar.gz ]] && command -v tar >/dev/null 2>&1; then
    listing="$(tar -tzf "$archive_path")"
    grep -Fq "$member" <<< "$listing" || fail "$label missing from archive: $member"
    pass "$label"
    return
  fi

  fail "cannot inspect handoff archive: $archive_path"
}

latest_apk() {
  ls -t "$ROOT_DIR"/android/app/build/outputs/apk/debug/*_debug.apk 2>/dev/null | head -n 1 || true
}

echo "== HelloTV TV-box delivery audit =="

echo
echo "== Refresh final-scope summaries =="
npm run -s tv-box:authorize >/dev/null
npm run -s tv-box:ux-audit >/dev/null
npm run -s tv-box:completion-audit >/dev/null
npm run -s tv-box:phone-camera-contract >/dev/null
npm run -s tv-box:phone-camera-scenarios-test >/dev/null
npm run -s tv-box:next-scenarios-test >/dev/null
npm run -s tv-box:command-center >/dev/null
npm run -s tv-box:site-readiness >/dev/null
NEXT_ALLOW_INSTALL=false NEXT_BUILD_DELIVERY=false npm run -s tv-box:next >/dev/null
pass "final-scope UX audit, completion audit, command center, site readiness and next-step report refreshed"

